-- 21 товар с рейтингом 4-5, 13 с рейтингом 2.9-4 и 8 с рейтингом 1-2.8.
-- У каждого обычного товара три отзыва и три оценки без текста.
WITH comments(product_id, texts) AS (VALUES
    (1, ARRAY['Рюкзак удобный, книги и ноутбук помещаются без труда.', 'Лямки не давят даже по дороге на учёбу.', 'Ткань плотная, карманы расположены удобно.']),
    (2, ARRAY['Картинка чёткая, автофокус хорошо справляется на интервью.', 'Удобно подключать микрофоны, звук получился чистым.', 'Зум плавный, камера пригодилась на съёмке мероприятия.']),
    (4, ARRAY['Клавиатура компактная, печатать на ней приятно.', 'Легко переключаюсь между ноутбуком и планшетом.', 'Круглые клавиши сначала непривычны, но работают тихо.']),
    (5, ARRAY['Лампа крепко держится на краю стола.', 'Плафон удобно направлять на книгу или тетрадь.', 'Кронштейн легко отрегулировать под рабочее место.']),
    (6, ARRAY['Ноутбук работает тихо и легко помещается в рюкзак.', 'Заряда хватает на рабочий день с документами и браузером.', 'Экран приятный, а большой трекпад очень удобен.']),
    (7, ARRAY['Экран яркий, пользоваться телефоном удобно даже на улице.', 'Камера хорошо снимает при дневном свете.', 'Смартфон компактный и быстро открывает приложения.']),
    (8, ARRAY['Уведомления удобно смотреть прямо на запястье.', 'Часы хорошо подходят для прогулок и тренировок.', 'С iPhone настроились быстро, экран читается легко.']),
    (9, ARRAY['Колонка звучит громко для своего размера.', 'Брали на прогулку, заряд продержался весь вечер.', 'Корпус удобный, подключение к телефону быстрое.']),
    (10, ARRAY['Мышь тихая и удобно лежит в руке.', 'Подключилась к ноутбуку без проблем, курсор движется плавно.', 'Кнопки действительно негромкие, для офиса подходит.']),
    (11, ARRAY['Клавиши приятно нажимать, места на столе стало больше.', 'Подсветка не слишком яркая, раскладка удобная.', 'Кабель можно снять, клавиатуру удобно перевозить.']),
    (12, ARRAY['Наушники хорошо сидят, для подкастов звука достаточно.', 'Футляр небольшой, удобно носить в кармане.', 'При разговоре меня слышно хорошо, подключение стабильное.']),
    (13, ARRAY['Аккумулятора хватает на несколько зарядок телефона.', 'Дисплей помогает понять, сколько заряда осталось.', 'Заряжает телефон быстро, в поездке выручил.']),
    (14, ARRAY['Через хаб подключил монитор и мышь к ноутбуку.', 'Корпус аккуратный, все нужные разъёмы под рукой.', 'Карта памяти читается без проблем, зарядка тоже работает.']),
    (15, ARRAY['На видеозвонках изображение заметно лучше встроенной камеры.', 'Шторка удобная, крепление на мониторе держится надёжно.', 'Для рабочих встреч качества изображения хватает.']),
    (16, ARRAY['Хлопок плотный и приятный к телу.', 'После стирки футболка сохранила форму.', 'Крой свободный, швы аккуратные.']),
    (17, ARRAY['Худи тёплое, начёс мягкий.', 'Свободный крой понравился, капюшон большой.', 'После стирки цвет не изменился, носить комфортно.']),
    (18, ARRAY['Шапка тёплая и не колется.', 'Отворот удобный, на голове сидит хорошо.', 'Цвет спокойный, вязка аккуратная.']),
    (19, ARRAY['Шоппер вместительный, ручки удобно носить на плече.', 'Ткань плотная, внутренний карман пригодился для ключей.', 'Сумка хорошо подходит для небольших покупок.']),
    (20, ARRAY['Кружка приятная на ощупь, ручка удобная.', 'Глазурь красивая, чай долго остаётся тёплым.', 'Пришла целой, объём для утреннего кофе подходящий.']),
    (21, ARRAY['Доска выглядит красиво, сыр на ней подавать удобно.', 'Дерево гладкое, следов грубой обработки нет.', 'Размер как раз для закусок на двоих.']),
    (22, ARRAY['Ваза выглядит симпатично, но оттенок чуть темнее фотографии.', 'Воду держит хорошо, поверхность оказалась довольно шероховатой.', 'Для небольшого букета подходит, цена показалась высокой.']),
    (23, ARRAY['Подставки защищают стол, но рисунок немного бледный.', 'Пробковая основа не скользит, края обработаны не идеально.', 'Для кружек размер удобный, ожидала более плотную фанеру.']),
    (24, ARRAY['Тушь хорошо разделяет ресницы, но к вечеру немного осыпается.', 'Щёточка удобная, хотя объёма хотелось бы больше.', 'Для дневного макияжа подходит, смывается не сразу.']),
    (25, ARRAY['Оттенки красивые, но светлые цвета слабо заметны.', 'Зеркало удобное, часть теней немного пылит.', 'Для повседневного макияжа неплохо, стойкость средняя.']),
    (26, ARRAY['Пудра матирует, но на сухой коже заметна.', 'Упаковка удобная, в течение дня приходится поправлять макияж.', 'Помол приятный, оттенок оказался немного светлее ожидаемого.']),
    (27, ARRAY['Цвет яркий, но после еды помаду нужно обновлять.', 'Наносится ровно, к концу дня немного сушит губы.', 'Оттенок красивый, но на чашке остаются следы.']),
    (28, ARRAY['Цвет насыщенный, но в один слой есть полосы.', 'Кисточка удобная, покрытие продержалось пару дней.', 'Лак сохнет дольше, чем ожидала, зато оттенок красивый.']),
    (29, ARRAY['Аромат свежий, но на мне держится недолго.', 'Цитрусовое начало понравилось, затем запах становится спокойнее.', 'На каждый день подходит, стойкость хотелось бы получше.']),
    (30, ARRAY['Аромат насыщенный, но для меня оказался тяжеловат.', 'Флакон красивый, стойкость хорошая, но запах на любителя.', 'Вечером звучит интересно, днём кажется слишком плотным.']),
    (31, ARRAY['Цветочный аромат приятный, но ожидала большей стойкости.', 'Флакон красивый, на коже аромат раскрывается мягко.', 'Запах понравился, хотя за такую цену хотелось бы дольше его ощущать.']),
    (32, ARRAY['Лёгкий фруктовый аромат, но быстро становится почти незаметным.', 'Для лета приятный, сладость поначалу показалась слишком сильной.', 'Флакон симпатичный, стойкость на моей коже средняя.']),
    (33, ARRAY['Цветы чувствуются сразу, но аромат оказался довольно насыщенным.', 'На одежде держится хорошо, на коже исчезает быстрее.', 'Композиция интересная, но перед покупкой лучше попробовать.']),
    (34, ARRAY['Изголовье мягкое, но сборка заняла больше времени, чем ожидали.', 'Кровать выглядит красиво, однако детали пришлось подгонять.', 'В целом удобная, но за эту цену ожидали более аккуратной отделки.']),
    (35, ARRAY['На сиденье обнаружилась неровная строчка, за такую цену неприятно.', 'Диван красивый, но сиденье оказалось слишком жёстким.', 'Обивка быстро мнётся, ожидали более аккуратного исполнения.']),
    (36, ARRAY['Ящик выдвигается с усилием, пришлось регулировать направляющие.', 'На углу была заметная царапина, упаковка не спасла.', 'Цвет понравился, но детали при сборке состыковались неровно.']),
    (37, ARRAY['Сиденье оказалось слишком жёстким для долгой работы.', 'Выглядит хорошо, но спинка мне неудобна.', 'За такую цену ожидал большего комфорта, быстро устаёт спина.']),
    (38, ARRAY['На тумбе обнаружили скол, пришлось обращаться к продавцу.', 'Внешний вид понравился, но дверцы установлены неровно.', 'При монтаже обнаружилась щель у раковины, потребовалась доработка.']),
    (39, ARRAY['Несколько яблок оказались с мягкими боками.', 'На вид красивые, но почти безвкусные.', 'Попались помятые плоды, свежесть партии разочаровала.']),
    (40, ARRAY['Мясо оказалось жёстким даже после отдыха перед нарезкой.', 'Кусок пришёл с большим количеством жил.', 'Ожидал более нежный стейк, результат после жарки разочаровал.']),
    (41, ARRAY['Кошка ела корм неохотно, пришлось вернуться к прежнему.', 'Гранулы оказались крупноваты для моего кота.', 'Питомцу вкус не понравился, миска осталась почти полной.']),
    (42, ARRAY['В упаковке оказалось много жидкости, качество не понравилось.', 'Куски нарезаны неровно, перед готовкой пришлось долго очищать.', 'Мясо показалось слишком водянистым после приготовления.'])
), entries AS (
    SELECT c.product_id, n,
           CASE WHEN n <= 3 THEN c.texts[n] END AS review,
           CASE WHEN c.product_id <= 21 THEN (ARRAY[5, 5, 4, 4, 5, 4])[n]
                WHEN c.product_id <= 34 THEN (ARRAY[4, 3, 3, 3, 4, 3])[n]
                ELSE (ARRAY[2, 2, 1, 2, 3, 2])[n] END AS rating
    FROM comments AS c
    CROSS JOIN generate_series(1, 6) AS n
), headphone_comments(n, review) AS (VALUES
    (1, 'Наушники удобно сидят, даже после долгой прогулки уши не устали.'),
    (2, 'Звук чистый, для музыки в дороге мне хватает.'),
    (3, 'Шумоподавление заметно приглушает разговоры в офисе.'),
    (4, 'Футляр компактный и легко помещается в карман.'),
    (5, 'С телефоном Samsung соединились сразу, переключение работает быстро.'),
    (6, 'Микрофон хорошо передаёт голос во время звонков.'),
    (7, 'Подобрала насадки из комплекта, теперь наушники держатся надёжно.'),
    (8, 'В транспорте слушать подкасты стало гораздо комфортнее.'),
    (9, 'Заряда хватает на дорогу и рабочие созвоны.'),
    (10, 'Режим звукового фона полезен, когда нужно услышать объявление.'),
    (11, 'Басы приятные и не заглушают голос в песнях.'),
    (12, 'Крышка футляра открывается легко, сами наушники не выпадают.'),
    (13, 'Нравится, что можно слушать музыку одним наушником.'),
    (14, 'Для звонков и аудиокниг подходят отлично.'),
    (15, 'На прогулке связь с телефоном не прерывалась.'),
    (16, 'Звук понравился, но к сенсорному управлению пришлось привыкать.'),
    (17, 'Шум поезда стал тише, хотя полностью не исчезает.'),
    (18, 'Лёгкие наушники, почти не ощущаются в ушах.'),
    (19, 'Музыка звучит объёмно, приложение помогает настроить эквалайзер.'),
    (20, 'На тренировке держались хорошо, посадка оказалась удобной.'),
    (21, 'Собеседники слышат меня нормально даже на улице без сильного ветра.'),
    (22, 'Зарядный футляр небольшой, но его приходится регулярно подзаряжать.'),
    (23, 'Понравилась быстрая настройка и понятное приложение.'),
    (24, 'В метро шумоподавление помогает не прибавлять громкость.'),
    (25, 'Высокие частоты звучат приятно, голос в подкастах разборчивый.'),
    (26, 'Наушники быстро подключаются после открытия футляра.'),
    (27, 'Комплектные насадки подошли не сразу, зато теперь посадка отличная.'),
    (28, 'Пользуюсь во время работы, на длительных встречах удобны.'),
    (29, 'Звук хороший, хотя хотелось бы чуть дольше работать без подзарядки.'),
    (30, 'Для повседневного использования удачная модель, футляр удобно носить с собой.')
), all_entries AS (
    SELECT product_id, n, review, rating FROM entries
    UNION ALL
    SELECT 3, n, review, CASE WHEN n % 3 = 0 THEN 4 ELSE 5 END
    FROM headphone_comments
    UNION ALL
    SELECT 3, n, NULL::text, CASE WHEN n % 3 = 0 THEN 4 ELSE 5 END
    FROM generate_series(31, 60) AS n
)
INSERT INTO product_review (buyer_id, product_id, review, rating, created_at, updated_at)
SELECT u.id, p.id, e.review, e.rating,
       NOW() - (e.product_id * 3 + e.n) * INTERVAL '1 day',
       NOW() - (e.product_id * 3 + e.n) * INTERVAL '1 day'
FROM all_entries AS e
JOIN product AS p ON p.id = e.product_id
JOIN "user" AS u ON u.email = 'seed.review-buyer.' || lpad((((e.product_id * 7 + e.n - 1) % 100) + 1)::text, 3, '0') || '@example.test'
JOIN buyer AS b ON b.user_id = u.id;
